mapper.select:
SELECT aa.CORP_GR AS corpGr , aa.COMPANY_NAME AS corpNm , (SELECT COUNT(1) FROM SJT0BM bm WHERE bm.corp_gr = aa.corp_gr AND bm.ymd BETWEEN TO_DATE(REPLACE(#{ym}, '-', ''), 'YYYYMM') AND LAST_DAY(TO_DATE(REPLACE(#{ym}, '-', ''), 'YYYYMM')) ) AS dataCount FROM SZX0AA aa WHERE aa.customer_gr = #{customerGr}
AND aa.corp_gr = #{corpGr}
ORDER BY aa.corp_gr ASC

SELECT aekm
  FROM SJX0JB
 WHERE balh_co = #{balhCo}

mapper.update:
UPDATE SJT0BK
   SET BAED_MTH       = #{baedMth}
     , BAEJ_MTH       = #{baejMth}
     , CASH_ILBAN_RT  = #{cashIlbanRt}
     , CASH_WOOS_RT   = #{cashWoosRt}
     , STOCK_ILBAN_RT = #{stockIlbanRt}
     , STOCK_WOOS_RT  = #{stockWoosRt}
     , BROK_YMD       = TO_DATE(REPLACE(#{brokYmd}, '-', ''), 'YYYYMMDD')
     , JUCHONG_YMD    = CASE WHEN #{juchongYmd} IS NOT NULL AND #{juchongYmd} != ''
                             THEN TO_DATE(REPLACE(#{juchongYmd}, '-', ''), 'YYYYMMDD')
                             ELSE NULL
                        END
     , ILBAN_AEK      = #{ilbanAek}
     , WOOS_AEK       = #{woosAek}
 WHERE CORP_GR = #{corpGr}
   AND TR_YMD  = TO_DATE(REPLACE(#{trYmd}, '-', ''), 'YYYYMMDD')
   AND TR_CD   = #{trCd}
   AND BALH_CO = #{balhCo}

